const galleries = [
  { name: "MINNYBAR Gallery", tabId: 725789734 },
  { name: "Piccadilly Pours Gallery", tabId: 725789735 },
  { name: "The Minnesocial Gallery", tabId: 725789736 },
  { name: "Agave Gallery", tabId: 725789737 }
];

for (const g of galleries) {
  try {
    const text = await browser.read({ tabId: g.tabId, maxChars: 500 });
    const imgCount = await browserjs(g.tabId, () => document.querySelectorAll('img').length);
    console.log(`${g.name} (Tab ${g.tabId}): title="${text.title || ''}", images=${imgCount}`);
  } catch (e) {
    console.log(`Error checking ${g.name}:`, e.message);
  }
}

